CREATE TABLE IF NOT EXISTS ton_topups (id text primary key, user_id int not null references users(id), amount_ton decimal(18,9) not null, amount_nano text not null, status text not null default 'pending', tx_hash text, confirmed_at timestamptz, created_at timestamptz not null default now()); CREATE INDEX IF NOT EXISTS ton_topups_user_id ON ton_topups(user_id); CREATE INDEX IF NOT EXISTS ton_topups_status ON ton_topups(status);
